draw(0.9*c--0.9*c+0.14*(d-c)--c+0.14*(d-c));
draw(0.92*d--0.92*d+0.14*(e-d)--d+0.14*(e-d));
label("$A$",a,NW);
label("$B$",b,SW);
label("$C$",c,SSE);
label("$D$",d,ESE);
label("$E$",e,NE);
label("1",(a+b)/2,W);
label("1",(b+c)/2,S);
label("1",(c+d)/2,SE);
label("1",(d+e)/2,E);
[/asy]

